using System;using System.IO;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {static class RememberValidation {public static void Run(Bridge bridge,string dir){D result=bridge.Call("login",J.Row("username","qa-native","password","QA-Only-Password-157","remember",true));string token=J.Text(result,"deviceToken");if(token.Length!=64)throw new Exception("Remember token missing");LoginStore.Save(false,"local","qa-native",true,true,token);if(LoginStore.Token(false)!=token)throw new Exception("Windows protected token roundtrip failed");string file=File.ReadAllText(Path.Combine(dir,"login-preferences","admin.json"));if(file.Contains(token)||file.Contains("QA-Only-Password-157"))throw new Exception("Plaintext secret in saved login");bridge.Call("resume",J.Row("token",LoginStore.Token(false)));using(var login=new Login(bridge))using(var timer=new System.Windows.Forms.Timer{Interval=5000}){timer.Tick+=(o,e)=>{timer.Stop();login.Close();};timer.Start();login.ShowDialog();timer.Stop();if(login.User==null||J.Text(login.User,"role")!="admin")throw new Exception("Startup automatic login failed");}LoginStore.Forget(false,true);if(LoginStore.Token(false)!=""||!J.Bool(LoginStore.Load(false),"rememberId"))throw new Exception("Auto-login clearing failed");LoginStore.Forget(false,false);if(J.Text(LoginStore.Load(false),"username")!="")throw new Exception("ID clearing failed");File.WriteAllText(Path.Combine(dir,"remember-test.json"),"{\"dpapiRoundtrip\":true,\"serverResume\":true,\"noPlaintextSecret\":true,\"clearOptions\":true}");}}}
